entries[77613] = { ["name"] = "Barmherzigkeit", ["text"] = "Sofort\nEure Zauber 'Blitzheilung', 'Heilung', 'Große Heilung' und 'Sühne' segnen das Ziel mit Barmherzigkeit, die seine durch den Priester erhaltene Heilung um 10% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar. Hält 15 Sek. lang an." }
