entries[77615] = { ["name"] = "Entkräftender Schleim", ["text"] = "Sofort\nSchleim spritzt aus dem Kessel und bedeckt jede Einheit im Raum. Der Schleim erhöht jeglichen erlittenen Schaden um 100% und unterdrückt jeglichen Wachstumskatalysator auf dem Ziel, wodurch er für eine Weile entfernt wird. Hält 15 Sek. lang an." }
